#!/bin/bash
# Generates per-app colour files from palette.sh. Safe to re-run; only writes generated files.
set -e
. "$HOME/.config/theme/palette.sh"
C="$HOME/.config"

# Alacritty (imported by alacritty.toml)
cat > "$C/alacritty/theme.toml" <<T
# GENERATED by ~/.config/theme/apply.sh - edit palette.sh instead
[colors.primary]
background = "#$BG"
foreground = "#$FG"
[colors.cursor]
text = "#$BG"
cursor = "#$FG"
[colors.selection]
text = "#$FG"
background = "#283457"
[colors.vi_mode_cursor]
text = "#$BG"
cursor = "#$LAVENDER"
[colors.search.matches]
foreground = "#$BG"
background = "#$CYAN"
[colors.search.focused_match]
foreground = "#$BG"
background = "#$ORANGE"
[colors.footer_bar]
foreground = "#$FG"
background = "#$SURFACE"
[colors.hints.start]
foreground = "#$BG"
background = "#$YELLOW"
[colors.hints.end]
foreground = "#$YELLOW"
background = "#$SURFACE"
[colors.line_indicator]
foreground = "#$BG"
background = "#$FG_MUTED"
[bell]
animation = "EaseOutExpo"
duration = 160
color = "#$BLUE"
[colors.normal]
black   = "#15161e"
red     = "#$RED"
green   = "#$GREEN"
yellow  = "#$YELLOW"
blue    = "#$BLUE"
magenta = "#$LAVENDER"
cyan    = "#$CYAN"
white   = "#a9b1d6"
[colors.bright]
black   = "#$FG_MUTED"
red     = "#$RED"
green   = "#$GREEN"
yellow  = "#$YELLOW"
blue    = "#$BLUE"
magenta = "#$LAVENDER"
cyan    = "#$CYAN"
white   = "#$FG"
T

# Polybar (included by config.ini)
cat > "$C/polybar/colors.ini" <<T
; GENERATED by ~/.config/theme/apply.sh - edit palette.sh instead
[colors]
background     = #E6$BG
background-alt = #$SURFACE
foreground     = #$FG
primary        = #$BLUE
secondary      = #$LAVENDER
highlight      = #$CYAN
alert          = #$RED
disabled       = #$FG_MUTED
border         = #$BORDER
on-accent      = #$BG
pill           = #$SURFACE
transparent    = #00000000
tag-primary    = %{F#$BLUE}
tag-secondary  = %{F#$LAVENDER}
tag-highlight  = %{F#$CYAN}
tag-alert      = %{F#$RED}
tag-warn       = %{F#$YELLOW}
tag-end        = %{F-}
T

# Rofi (imported by custom.rasi)
cat > "$C/rofi/colors.rasi" <<T
/* GENERATED by ~/.config/theme/apply.sh - edit palette.sh instead */
* {
    bg:        #${BG}F2;
    bg-alt:    #$SURFACE;
    fg:        #$FG;
    fg-muted:  #$FG_MUTED;
    accent:    #$BLUE;
    accent-2:  #$LAVENDER;
    highlight: #$CYAN;
    alert:     #$RED;
    border:    #$BORDER;
    bg-solid:  #$BG;
    glass:     #${BG}D9;
    overlay:   #${BG_ALT}E3;
    sel:       #${BLUE}33;
    sel-edge:  #${BLUE}66;
    divider:   #${BORDER}B3;
}
T

# Dunst (only used once dunst is installed and replaces xfce4-notifyd)
mkdir -p "$C/dunst"
cat > "$C/dunst/dunstrc" <<T
# GENERATED by ~/.config/theme/apply.sh - edit palette.sh instead
[global]
    monitor = 0
    follow = mouse
    width = (300, 380)
    origin = top-right
    offset = (16, 56)
    gap_size = 8
    padding = 14
    horizontal_padding = 16
    frame_width = 2
    corner_radius = 12
    font = FiraCode Nerd Font 10
    markup = full
    format = "<b>%s</b>\\n%b"
    icon_theme = Papirus-Dark
    enable_recursive_icon_lookup = true
    icon_position = left
    max_icon_size = 48
    history_length = 50
    mouse_left_click = close_current
    mouse_right_click = close_all
    mouse_middle_click = do_action, close_current
    transparency = 0
[urgency_low]
    background = "#$BG"
    foreground = "#$FG_MUTED"
    frame_color = "#$BORDER"
    timeout = 5
[urgency_normal]
    background = "#$BG"
    foreground = "#$FG"
    frame_color = "#$BLUE"
    timeout = 8
[urgency_critical]
    background = "#$BG"
    foreground = "#$FG"
    frame_color = "#$RED"
    timeout = 0
T

# GTK3 theme "TokyoNight" (Adwaita base + palette), and libadwaita/GTK4 colour overrides
mkdir -p "$HOME/.themes/TokyoNight/gtk-3.0"
cat > "$HOME/.themes/TokyoNight/index.theme" <<T
[Desktop Entry]
Type=X-GNOME-Metatheme
Name=TokyoNight
Comment=Generated from ~/.config/theme/palette.sh
[X-GNOME-Metatheme]
GtkTheme=TokyoNight
MetacityTheme=TokyoNight
IconTheme=Qogir-dark
T
python3 "$C/theme/gen-gtk3.py" || echo "note: GTK3 theme skipped (install python-gobject and gtk3 to enable it)"   # recolours GTK Adwaita-dark with the palette (cached)

# libadwaita / GTK4 apps (e.g. File Roller)
mkdir -p "$HOME/.config/gtk-4.0"
cat > "$HOME/.config/gtk-4.0/tokyonight.css" <<T
/* GENERATED by ~/.config/theme/apply.sh - edit palette.sh instead */
@define-color accent_bg_color #$BLUE;
@define-color accent_fg_color #$BG;
@define-color accent_color #$BLUE;
@define-color window_bg_color #$BG;
@define-color window_fg_color #$FG;
@define-color view_bg_color #$BG_ALT;
@define-color view_fg_color #$FG;
@define-color headerbar_bg_color #$BG;
@define-color headerbar_fg_color #$FG;
@define-color headerbar_border_color #$BORDER;
@define-color card_bg_color #$SURFACE;
@define-color card_fg_color #$FG;
@define-color popover_bg_color #$SURFACE;
@define-color popover_fg_color #$FG;
@define-color dialog_bg_color #$BG;
@define-color dialog_fg_color #$FG;
@define-color sidebar_bg_color #$BG_ALT;
@define-color sidebar_fg_color #$FG;
@define-color destructive_bg_color #$RED;
@define-color success_bg_color #$GREEN;
@define-color warning_bg_color #$YELLOW;
@define-color error_bg_color #$RED;
T

# bspwm border colours, applied live if bspwm is running
if [ -z "${RICE_NO_BSPC:-}" ] && command -v bspc >/dev/null && pgrep -x bspwm >/dev/null; then
  bspc config normal_border_color  "#$BORDER"
  bspc config active_border_color  "#$LAVENDER"
  bspc config focused_border_color "#$BLUE"
  bspc config presel_feedback_color "#$CYAN"
fi
echo "theme applied"
